CREATE TABLE IF NOT EXISTS filers (cik CHAR(10) PRIMARY KEY,name TEXT NOT NULL,updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS filings (accession TEXT PRIMARY KEY,cik CHAR(10) NOT NULL REFERENCES filers(cik),form_type TEXT NOT NULL,filed_date DATE NOT NULL,report_period DATE NOT NULL,is_amendment BOOLEAN NOT NULL DEFAULT FALSE,primary_document TEXT,information_table_document TEXT,source_url TEXT NOT NULL,loaded_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS holdings (accession TEXT NOT NULL REFERENCES filings(accession) ON DELETE CASCADE,row_number INTEGER NOT NULL,name_of_issuer TEXT NOT NULL,title_of_class TEXT,cusip TEXT,figi TEXT,value_usd BIGINT NOT NULL,shares_or_principal NUMERIC(24,4) NOT NULL,shares_type TEXT,put_call TEXT,investment_discretion TEXT,other_manager TEXT,voting_sole NUMERIC(24,4),voting_shared NUMERIC(24,4),voting_none NUMERIC(24,4),PRIMARY KEY (accession,row_number));
CREATE INDEX IF NOT EXISTS idx_filings_cik_period ON filings(cik,report_period); CREATE INDEX IF NOT EXISTS idx_holdings_cusip ON holdings(cusip);
